mapper.sql:
where 1=1

		and cusr_llave = #{llaveTabla}


		and cusr_estado = #{estado}


		and cusr_identificacion = #{identificacion}


		and cusr_nombre = #{nombre}


		and cusr_telefono = #{telefono}


		and (upper(cusr_nombre) like upper('%' || #{filtroParametro} || '%') or upper(cusr_identificacion) = upper( #{filtroParametro}))
